export const enclosureInformation = `<p class="detail-lead">一层一层，看清设备的结构。</p><ol class="detail-steps"><li><h3>顶盖</h3><p>覆盖上方硬件，与底壳形成完整外形。首页展示合拢状态，这里的分解视图将它抬起，便于观察内部。</p></li><li><h3>双层主板</h3><p>上层负责采集与控制，下层负责供电与驱动。图中的间距经过拉开，用来说明装配关系，不代表实际安装间隙。</p></li><li><h3>底壳</h3><p>容纳主板与连接部件，保留模型中的侧面开口、壳体接缝与底部支脚。</p></li></ol><p class="detail-footnote">结构依据当前 CAD 模型展示；网页中的暖白塑料外观用于产品预览，实物材料与表面工艺以实际制作版本为准。</p>`;

export const overview = `<p class="detail-lead">一台会观察环境、在本地决定何时浇水的设备。</p><ul class="detail-list"><li><strong>双层主板协同</strong><p>上板连接 ESP32-C3、OLED 与传感器；下板组织供电，驱动水泵并连接舵机。</p></li><li><strong>根据植物状态判断</strong><p>结合土壤、空气温湿度和雨量计算需求，满足条件后分次开泵。</p></li><li><strong>配置一次，独立运行</strong><p>网页生成种植场景配置，通过蓝牙写入设备；长期运行由设备自行完成。</p></li></ul><a class="detail-action" href="#product">了解工作原理与双层硬件 →</a>`;

export function connectionInformation(compatible) {
 return `<p class="detail-lead">先唤醒，再连接。</p><ol class="detail-steps"><li><h3>按设备外置按钮</h3><p>深度休眠期间蓝牙不工作，网页不能远程唤醒设备。</p></li><li><h3>选择并连接设备</h3><p>开启系统蓝牙，点击“连接浇水设备”，在浏览器设备列表中授权连接。</p></li><li><h3>等待握手完成</h3><p>连接后核对设备与固件信息；握手成功后再读取状态或写入配置。</p></li></ol><div class="detail-note"><strong>${compatible ? '当前浏览器提供蓝牙接口' : '当前浏览器未提供蓝牙接口'}</strong><p>${compatible ? '连接仍需要系统蓝牙、用户授权和匹配的设备固件。' : '请使用支持 Web Bluetooth 的浏览器，并在 localhost 或 HTTPS 页面中连接。备用连接方式尚未确定。'}设备休眠或断开后，请重新唤醒并连接。</p></div>`;
}

export const workspaceInformation = `<p class="detail-lead">从了解设备，到让它照料你的植物。</p><ul class="workspace-links detail-list"><li><a href="#product"><strong>产品介绍</strong><span>了解工作原理、双层主板和使用步骤</span><b aria-hidden="true">→</b></a></li><li><a href="#configure"><strong>个性化库编译</strong><span>填写植物与场景，生成、检查并写入配置</span><b aria-hidden="true">→</b></a></li><li><a href="#device"><strong>硬件情况查看</strong><span>连接后查看采样、运行模式和最近一周记录</span><b aria-hidden="true">→</b></a></li></ul><p class="detail-footnote">运行结果以设备实际反馈为准。模拟设备仅用于体验，不会写入真实硬件。</p>`;

export const principleInformation = `<p class="detail-lead">把环境变化，转成一次有依据的浇水决定。</p><ul class="detail-list"><li><strong>先读懂环境</strong><p>读取土壤与雨量的模拟信号，以及空气温度、湿度。土壤和雨量多次采样后取中位数，减少读数抖动。</p></li><li><strong>再计算需求</strong><p>土壤干燥度、温度胁迫和空气干燥度共同形成 0–100 的浇水需求值。它表示相对需求，不是土壤湿度百分比。</p></li><li><strong>浇水前再检查</strong><p>检测到下雨或土壤数据无效时，自动浇水需求归零。只有达到配置阈值、满足季节间隔且没有进行中的浇水周期，设备才会启动水泵。</p></li><li><strong>分次给水</strong><p>按“开泵—等待—再次开泵”执行脉冲浇水。实际出水量由实测流量和开泵时间共同决定。</p></li></ul><div class="detail-note"><strong>网页配置，设备决策</strong><p>网页根据植物、地点、栽培方式、光照与水源生成临时配置；浏览器通过 BLE 写入设备。配置保存后，设备独立采样、判断与运行，不需要持续打开网页。</p></div>`;

export const hardwareInformation = `<p class="detail-lead">双层结构，让采集与控制、供电与驱动各有位置。</p><div class="board-comparison"><figure><img src="/static/assets/boards/upper-10-01.png" alt="10-01 版本上板正面 PCB 工程图" loading="lazy"><figcaption>上板 · 采集与控制</figcaption></figure><figure><img src="/static/assets/boards/lower-10-01.png" alt="10-01 版本下板正面 PCB 工程图" loading="lazy"><figcaption>下板 · 供电与驱动</figcaption></figure></div><ul class="detail-list"><li><strong>上板：连接环境与主控</strong><p>通过插座连接带 OLED 的 ESP32-C3 开发板，接入温湿度、土壤、雨量传感器，采集太阳能输入电压，并输出水泵与舵机控制信号。传感器共用受控电源，采样完成后统一关闭。</p></li><li><strong>下板：组织供电与执行</strong><p>设置 18650 电池座、电源连接、开关与保护器件；AO3400A MOS 驱动水泵，续流二极管处理关泵时的感性负载，舵机通过接口连接。</p></li><li><strong>板间连接：供电、地与信号</strong><p>两块板通过连接器传递电源、地、水泵、舵机和太阳能相关信号。系统目标供电为 5V，电源模块的实际输出能力需随整机验证。</p></li><li><strong>执行器各司其职</strong><p>水泵负责浇水，舵机负责擦拭雨量板。水泵使用高电平开启、低电平关闭的 MOS 控制。</p></li></ul><p class="detail-footnote">依据浇水6代-v2 的 10-01 版本资料，图片为 PCB 工程图。太阳能输入电压可采样；电池电量与系统 VIN 没有独立测量通道。</p>`;

export const workflowInformation = `<p class="detail-lead">一次唤醒，完成一个运行闭环。</p><ol class="detail-steps"><li><h3>启动与准备</h3><p>加载保存的配置，先保持水泵关闭、传感器电源关闭，再初始化显示、采样与通信。</p></li><li><h3>供电与采样</h3><p>开启传感器电源，等待稳定，读取温湿度、土壤、雨量及太阳能输入电压；传感器采样结束后断电。</p></li><li><h3>判断与执行</h3><p>检查数据有效性、降雨、需求阈值与季节间隔。满足条件时执行脉冲浇水；雨量板擦拭由舵机负责。</p></li><li><h3>记录与休眠</h3><p>记录采样与运行结果，关泵并完成动作收尾。长期模式随后进入深度休眠，等待下一次唤醒。</p></li></ol><h3 class="detail-subheading">选择适合当前阶段的模式</h3><dl class="detail-modes"><div><dt>DISPLAY <span>展示 / 调试</span></dt><dd>观察采样与 OLED 显示，资料默认约每 2 秒采样一次。</dd></div><div><dt>PREPARE <span>准备 / 校准</span></dt><dd>正式运行前采集基准，资料默认准备窗口约 10 分钟。</dd></div><div><dt>LONGRUN <span>长期运行</span></dt><dd>周期唤醒、采样与必要浇水，资料默认约每 2 小时唤醒一次。</dd></div></dl><p class="detail-footnote">时间为资料中的默认行为，实际参数与可用操作以当前固件及设备反馈为准。</p>`;

export const guideInformation = `<p class="detail-lead">先确认实物，再开始自动照料。</p><ol class="detail-steps"><li><h3>接好传感器与水路</h3><p>核对供电、板间连接、水泵与舵机接口；准备水源，确认出水位置。分别验证各负载工作正常。</p></li><li><h3>完成实物标定</h3><p>确认土壤干湿端点、雨量方向与阈值、采样等待时间，测量水泵流量，并检查舵机擦拭角度和动作范围。</p></li><li><h3>唤醒并连接</h3><p>按设备外置按钮，通过支持 Web Bluetooth 的浏览器连接，等待设备握手成功。</p></li><li><h3>生成并写入配置</h3><p>在个性化库编译页面填写植物、地点、光照、栽培方式与水源。检查推荐参数后下发配置，确认设备完成校验和保存。</p></li><li><h3>验证后进入长期运行</h3><p>使用 DISPLAY 观察读数，使用 PREPARE 采集基准。确认实际出水、土壤状态与运行反馈后启用 LONGRUN，并查看近期记录。</p></li></ol><div class="detail-note"><strong>10-01 样板需要重新标定</strong><p>不要直接套用旧版本的土壤 ADC、雨量阈值或水泵流量。网页中的水量与续航属于估算，不能替代当前样板的实测结果。</p></div><a class="detail-action" href="#configure">开始配置你的种植场景 →</a>`;
